const sub = $('Room submission').first().json.body ?? {};

let verdict = null;
try {
  const raw = $input.first().json?.choices?.[0]?.message?.content ?? '';
  verdict = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  verdict = null;
}

// Fail closed. Anything we could not read stays 'pending', which the anon key cannot see.
const status = verdict === null ? 'pending' : (verdict.safe === true ? 'approved' : 'blocked');

return [{
  json: {
    message: String(sub.message ?? '').slice(0, 500),
    email: sub.email || null,
    status,
    block_reason: status === 'approved' ? null : (verdict?.reason ?? 'moderation unavailable'),
  },
}];
